244	void rmsnorm(float* o, float* x, float* weight, int size) {
245	    // calculate sum of squares
246	    float ss = 0.0f;
247	    for (int j = 0; j < size; j++) {
248	        ss += x[j] * x[j];
249	    }
250	    ss /= size;
251	    ss += 1e-5f;
252	    ss = 1.0f / sqrtf(ss);
253	    // normalize and scale
254	    for (int j = 0; j < size; j++) {
255	        o[j] = weight[j] * (ss * x[j]);
256	    }
257	}
