259	void softmax(float* x, int size) {
260	    // find max value (for numerical stability)
261	    float max_val = x[0];
262	    for (int i = 1; i < size; i++) {
263	        if (x[i] > max_val) {
264	            max_val = x[i];
265	        }
266	    }
267	    // exp and sum
268	    float sum = 0.0f;
269	    for (int i = 0; i < size; i++) {
270	        x[i] = expf(x[i] - max_val);
271	        sum += x[i];
272	    }
273	    // normalize
274	    for (int i = 0; i < size; i++) {
275	        x[i] /= sum;
276	    }
277	}
