296	    Config* p = &transformer->config;
297	    TransformerWeights* w = &transformer->weights;
298	    RunState* s = &transformer->state;
299	    float *x = s->x;
300	    int dim = p->dim;
301	    int kv_dim = (p->dim * p->n_kv_heads) / p->n_heads;
302	    int kv_mul = p->n_heads / p->n_kv_heads; // integer multiplier of the kv sharing in multiquery
303	    int hidden_dim =  p->hidden_dim;
304	    int head_size = dim / p->n_heads;
305	
306	    // copy the token embedding into x
307	    float* content_row = w->token_embedding_table + token * dim;
308	    memcpy(x, content_row, dim*sizeof(*x));
309	
310	    // forward all the layers
311	    for(unsigned long long l = 0; l < p->n_layers; l++) {
312	
313	        // attention rmsnorm
314	        rmsnorm(s->xb, x, w->rms_att_weight + l*dim, dim);
315	
316	        // key and value point to the kv cache
317	        int loff = l * p->seq_len * kv_dim; // kv cache layer offset for convenience
318	        s->k = s->key_cache + loff + pos * kv_dim;
319	        s->v = s->value_cache + loff + pos * kv_dim;
320	
321	        // qkv matmuls for this position
322	        matmul(s->q, s->xb, w->wq + l*dim*dim, dim, dim);
323	        matmul(s->k, s->xb, w->wk + l*dim*kv_dim, dim, kv_dim);
324	        matmul(s->v, s->xb, w->wv + l*dim*kv_dim, dim, kv_dim);
325	
326	        // RoPE relative positional encoding: complex-valued rotate q and k in each head
327	        for (int i = 0; i < dim; i+=2) {
328	            int head_dim = i % head_size;
329	            float freq = 1.0f / powf(10000.0f, head_dim / (float)head_size);
330	            float val = pos * freq;
331	            float fcr = cosf(val);
332	            float fci = sinf(val);
333	            int rotn = i < kv_dim ? 2 : 1; // how many vectors? 2 = q & k, 1 = q only
334	            for (int v = 0; v < rotn; v++) {
335	                float* vec = v == 0 ? s->q : s->k; // the vector to rotate (query or key)
336	                float v0 = vec[i];
337	                float v1 = vec[i+1];
338	                vec[i]   = v0 * fcr - v1 * fci;
339	                vec[i+1] = v0 * fci + v1 * fcr;
340	            }
341	        }
342	
343	        // multihead attention. iterate over all heads
344	        int h;
345	        #pragma omp parallel for private(h)
346	        for (h = 0; h < p->n_heads; h++) {
347	            // get the query vector for this head
348	            float* q = s->q + h * head_size;
349	            // attention scores for this head
350	            float* att = s->att + h * p->seq_len;
351	            // iterate over all timesteps, including the current one
352	            for (int t = 0; t <= pos; t++) {
353	                // get the key vector for this head and at this timestep
354	                float* k = s->key_cache + loff + t * kv_dim + (h / kv_mul) * head_size;
355	                // calculate the attention score as the dot product of q and k
356	                float score = 0.0f;
357	                for (int i = 0; i < head_size; i++) {
358	                    score += q[i] * k[i];
359	                }
360	                score /= sqrtf(head_size);
361	                // save the score to the attention buffer
362	                att[t] = score;
363	            }
364	
365	            // softmax the scores to get attention weights, from 0..pos inclusively
366	            softmax(att, pos + 1);
367	
368	            // weighted sum of the values, store back into xb
369	            float* xb = s->xb + h * head_size;
370	            memset(xb, 0, head_size * sizeof(float));
371	            for (int t = 0; t <= pos; t++) {
372	                // get the value vector for this head and at this timestep
373	                float* v = s->value_cache + loff + t * kv_dim + (h / kv_mul) * head_size;
374	                // get the attention weight for this timestep
375	                float a = att[t];
376	                // accumulate the weighted value into xb
377	                for (int i = 0; i < head_size; i++) {
378	                    xb[i] += a * v[i];
379	                }
380	            }
381	        }
382	
383	        // final matmul to get the output of the attention
384	        matmul(s->xb2, s->xb, w->wo + l*dim*dim, dim, dim);
385	
386	        // residual connection back into x
387	        for (int i = 0; i < dim; i++) {
388	            x[i] += s->xb2[i];
389	        }
390	
391	        // ffn rmsnorm
392	        rmsnorm(s->xb, x, w->rms_ffn_weight + l*dim, dim);
393	
394	        // Now for FFN in PyTorch we have: self.w2(F.silu(self.w1(x)) * self.w3(x))
395	        // first calculate self.w1(x) and self.w3(x)
396	        matmul(s->hb, s->xb, w->w1 + l*dim*hidden_dim, dim, hidden_dim);
397	        matmul(s->hb2, s->xb, w->w3 + l*dim*hidden_dim, dim, hidden_dim);
398	
399	        // SwiGLU non-linearity
400	        for (int i = 0; i < hidden_dim; i++) {
401	            float val = s->hb[i];
402	            // silu(x)=x*σ(x), where σ(x) is the logistic sigmoid
403	            val *= (1.0f / (1.0f + expf(-val)));
404	            // elementwise multiply with w3(x)
405	            val *= s->hb2[i];
406	            s->hb[i] = val;
407	        }
408	
409	        // final matmul to get the output of the ffn
410	        matmul(s->xb, s->hb, w->w2 + l*dim*hidden_dim, hidden_dim, dim);
411	
412	        // residual connection
413	        for (int i = 0; i < dim; i++) {
414	            x[i] += s->xb[i];
415	        }
416	    }
417	
418	    // final rmsnorm
419	    rmsnorm(x, x, w->rms_final_weight, dim);
420	
421	    // classifier into logits
422	    matmul(s->logits, x, w->wcls, p->dim, p->vocab_size);
423	    return s->logits;
424	}
