427	// The Byte Pair Encoding (BPE) Tokenizer that translates strings <-> tokens
428	
429	typedef struct {
430	    char *str;
431	    int id;
432	} TokenIndex;
433	
434	typedef struct {
435	    char** vocab;
436	    float* vocab_scores;
437	    TokenIndex *sorted_vocab;
438	    int vocab_size;
439	    unsigned int max_token_length;
440	    unsigned char byte_pieces[512]; // stores all single-byte strings
441	} Tokenizer;
442	
443	int compare_tokens(const void *a, const void *b) {
444	    return strcmp(((TokenIndex*)a)->str, ((TokenIndex*)b)->str);
445	}
446	
447	void build_tokenizer(Tokenizer* t, char* tokenizer_path, int vocab_size) {
448	    // i should have written the vocab_size into the tokenizer file... sigh
449	    t->vocab_size = vocab_size;
450	    // malloc space to hold the scores and the strings
451	    t->vocab = (char**)malloc(vocab_size * sizeof(char*));
452	    t->vocab_scores = (float*)malloc(vocab_size * sizeof(float));
453	    t->sorted_vocab = NULL; // initialized lazily
454	    for (int i = 0; i < 256; i++) {
455	        t->byte_pieces[i * 2] = (unsigned char)i;
456	        t->byte_pieces[i * 2 + 1] = '\0';
457	    }
458	    // read in the file
459	    FILE *file = fopen(tokenizer_path, "rb");
460	    if (!file) { fprintf(stderr, "couldn't load %s\n", tokenizer_path); exit(EXIT_FAILURE); }
461	    if (fread(&t->max_token_length, sizeof(int), 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE); }
462	    int len;
463	    for (int i = 0; i < vocab_size; i++) {
464	        if (fread(t->vocab_scores + i, sizeof(float), 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE);}
465	        if (fread(&len, sizeof(int), 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE); }
466	        t->vocab[i] = (char *)malloc(len + 1);
467	        if (fread(t->vocab[i], len, 1, file) != 1) { fprintf(stderr, "failed read\n"); exit(EXIT_FAILURE); }
468	        t->vocab[i][len] = '\0'; // add the string terminating token
469	    }
470	    fclose(file);
471	}
472	
473	void free_tokenizer(Tokenizer* t) {
474	    for (int i = 0; i < t->vocab_size; i++) { free(t->vocab[i]); }
475	    free(t->vocab);
476	    free(t->vocab_scores);
477	    free(t->sorted_vocab);
478	}
479	
480	char* decode(Tokenizer* t, int prev_token, int token) {
481	    char *piece = t->vocab[token];
482	    // following BOS (1) token, sentencepiece decoder strips any leading whitespace (see PR #89)
483	    if (prev_token == 1 && piece[0] == ' ') { piece++; }
484	    // careful, some tokens designate raw bytes, and look like e.g. '<0x01>'
485	    // parse this and convert and return the actual byte
486	    unsigned char byte_val;
487	    if (sscanf(piece, "<0x%02hhX>", &byte_val) == 1) {
488	        piece = (char*)t->byte_pieces + byte_val * 2;
489	    }
490	    return piece;
491	}
492	
493	void safe_printf(char *piece) {
494	    // piece might be a raw byte token, and we only want to print printable chars or whitespace
495	    // because some of the other bytes can be various control codes, backspace, etc.
496	    if (piece == NULL) { return; }
497	    if (piece[0] == '\0') { return; }
498	    if (piece[1] == '\0') {
499	        unsigned char byte_val = piece[0];
500	        if (!(isprint(byte_val) || isspace(byte_val))) {
501	            return; // bad byte, don't print it
502	        }
503	    }
504	    printf("%s", piece);
505	}
506	
507	int str_lookup(char *str, TokenIndex *sorted_vocab, int vocab_size) {
508	    // efficiently find the perfect match for str in vocab, return its index or -1 if not found
509	    TokenIndex tok = { .str = str }; // acts as the key to search for
510	    TokenIndex *res = bsearch(&tok, sorted_vocab, vocab_size, sizeof(TokenIndex), compare_tokens);
511	    return res != NULL ? res->id : -1;
512	}
513	
514	void encode(Tokenizer* t, char *text, int8_t bos, int8_t eos, int *tokens, int *n_tokens) {
515	    // encode the string text (input) into an upper-bound preallocated tokens[] array
516	    // bos != 0 means prepend the BOS token (=1), eos != 0 means append the EOS token (=2)
517	    if (text == NULL) { fprintf(stderr, "cannot encode NULL text\n"); exit(EXIT_FAILURE); }
518	
519	    if (t->sorted_vocab == NULL) {
520	        // lazily malloc and sort the vocabulary
521	        t->sorted_vocab = malloc(t->vocab_size * sizeof(TokenIndex));
522	        for (int i = 0; i < t->vocab_size; i++) {
523	            t->sorted_vocab[i].str = t->vocab[i];
524	            t->sorted_vocab[i].id = i;
525	        }
526	        qsort(t->sorted_vocab, t->vocab_size, sizeof(TokenIndex), compare_tokens);
527	    }
528	
529	    // create a temporary buffer that will store merge candidates of always two consecutive tokens
530	    // *2 for concat, +1 for null terminator +2 for UTF8 (in case max_token_length is 1)
531	    char* str_buffer = malloc((t->max_token_length*2 +1 +2) * sizeof(char));
532	    size_t str_len = 0;
533	
534	    // start at 0 tokens
535	    *n_tokens = 0;
536	
537	    // add optional BOS (=1) token, if desired
538	    if (bos) tokens[(*n_tokens)++] = 1;
539	
540	    // add_dummy_prefix is true by default
541	    // so prepend a dummy prefix token to the input string, but only if text != ""
542	    // TODO: pretty sure this isn't correct in the general case but I don't have the
543	    // energy to read more of the sentencepiece code to figure out what it's doing
544	    if (text[0] != '\0') {
545	        int dummy_prefix = str_lookup(" ", t->sorted_vocab, t->vocab_size);
546	        tokens[(*n_tokens)++] = dummy_prefix;
547	    }
548	
549	    // Okay UTF-8 time. This will get messy. Here is the reference from Wikipedia:
550	    // Code point ↔ UTF-8 conversion
551	    // First code point	Last code point	Byte 1	Byte 2	Byte 3	Byte 4
552	    // U+0000	U+007F	    0xxxxxxx
553	    // U+0080	U+07FF	    110xxxxx	10xxxxxx
554	    // U+0800	U+FFFF	    1110xxxx	10xxxxxx	10xxxxxx
555	    // U+10000	U+10FFFF    11110xxx	10xxxxxx	10xxxxxx	10xxxxxx
556	
557	    // process the raw (UTF-8) byte sequence of the input string
558	    for (char *c = text; *c != '\0'; c++) {
559	
560	        // reset buffer if the current byte is ASCII or a leading byte
561	        // 0xC0 is 11000000, so (*c & 0xC0) keeps the first 2 bits and zeros the rest
562	        // 0x80 is 10000000
563	        // in UTF-8, all continuation bytes start with "10" in first two bits
564	        // so in English this is: "if this byte is not a continuation byte"
565	        if ((*c & 0xC0) != 0x80) {
566	            // this byte must be either a leading byte (11...) or an ASCII char (0x...)
567	            // => reset our location, as we're starting a new UTF-8 codepoint
568	            str_len = 0;
569	        }
570	
571	        // append the current byte to the buffer
572	        str_buffer[str_len++] = *c; // ++ is post-increment, incremented after this line
573	        str_buffer[str_len] = '\0';
574	
575	        // while the next character is a continuation byte, continue appending
576	        // but if there are too many of them, just stop to avoid overruning str_buffer size.
577	        if ((*(c+1) & 0xC0) == 0x80 && str_len < 4) {
578	            continue;
579	        }
580	
581	        // ok c+1 is not a continuation byte, so we've read in a full codepoint
582	        int id = str_lookup(str_buffer, t->sorted_vocab, t->vocab_size);
583	
584	        if (id != -1) {
585	            // we found this codepoint in vocab, add it as a token
586	            tokens[(*n_tokens)++] = id;
587	        } else {
588	            // byte_fallback encoding: just encode each byte as a token
589	            // +3 is here because the first 3 vocab elements are <unk>, <s>, </s>
590	            // so the individual bytes only start at index 3
591	            for (int i=0; i < str_len; i++) {
592	                tokens[(*n_tokens)++] = (unsigned char)str_buffer[i] + 3;
593	            }
594	        }
595	        str_len = 0; // protect against a sequence of stray UTF8 continuation bytes
596	    }
597	
598	    // merge the best consecutive pair each iteration, according the scores in vocab_scores
599	    while (1) {
600	        float best_score = -1e10;
601	        int best_id = -1;
602	        int best_idx = -1;
603	
604	        for (int i=0; i < (*n_tokens-1); i++) {
605	            // check if we can merge the pair (tokens[i], tokens[i+1])
606	            sprintf(str_buffer, "%s%s", t->vocab[tokens[i]], t->vocab[tokens[i+1]]);
607	            int id = str_lookup(str_buffer, t->sorted_vocab, t->vocab_size);
608	            if (id != -1 && t->vocab_scores[id] > best_score) {
609	                // this merge pair exists in vocab! record its score and position
610	                best_score = t->vocab_scores[id];
611	                best_id = id;
612	                best_idx = i;
613	            }
614	        }
615	
616	        if (best_idx == -1) {
617	            break; // we couldn't find any more pairs to merge, so we're done
618	        }
619	
620	        // merge the consecutive pair (best_idx, best_idx+1) into new token best_id
621	        tokens[best_idx] = best_id;
622	        // delete token at position best_idx+1, shift the entire sequence back 1
623	        for (int i = best_idx+1; i < (*n_tokens-1); i++) {
624	            tokens[i] = tokens[i+1];
625	        }
626	        (*n_tokens)--; // token length decreased
627	    }
628	
629	    // add optional EOS (=2) token, if desired
630	    if (eos) tokens[(*n_tokens)++] = 2;
631	
632	    free(str_buffer);
633	}
