789	// generation loop
790	
791	void generate(Transformer *transformer, Tokenizer *tokenizer, Sampler *sampler, char *prompt, int steps) {
792	    char *empty_prompt = "";
793	    if (prompt == NULL) { prompt = empty_prompt; }
794	
795	    // encode the (string) prompt into tokens sequence
796	    int num_prompt_tokens = 0;
797	    int* prompt_tokens = (int*)malloc((strlen(prompt)+3) * sizeof(int)); // +3 for '\0', ?BOS, ?EOS
798	    encode(tokenizer, prompt, 1, 0, prompt_tokens, &num_prompt_tokens);
799	    if (num_prompt_tokens < 1) {
800	        fprintf(stderr, "something is wrong, expected at least 1 prompt token\n");
801	        exit(EXIT_FAILURE);
802	    }
803	
804	    // start the main loop
805	    long start = 0;  // used to time our code, only initialized after first iteration
806	    int next;        // will store the next token in the sequence
807	    int token = prompt_tokens[0]; // kick off with the first token in the prompt
808	    int pos = 0;     // position in the sequence
809	    while (pos < steps) {
810	
811	        // forward the transformer to get logits for the next token
812	        float* logits = forward(transformer, token, pos);
813	
814	        // advance the state machine
815	        if (pos < num_prompt_tokens - 1) {
816	            // if we are still processing the input prompt, force the next prompt token
817	            next = prompt_tokens[pos + 1];
818	        } else {
819	            // otherwise sample the next token from the logits
820	            next = sample(sampler, logits);
821	        }
822	        pos++;
823	
824	        // data-dependent terminating condition: the BOS (=1) token delimits sequences
825	        if (next == 1) { break; }
826	
827	        // print the token as string, decode it with the Tokenizer object
828	        char* piece = decode(tokenizer, token, next);
829	        safe_printf(piece); // same as printf("%s", piece), but skips "unsafe" bytes
830	        fflush(stdout);
831	        token = next;
832	
833	        // init the timer here because the first iteration can be slower
834	        if (start == 0) { start = time_in_ms(); }
835	    }
836	    printf("\n");
837	
838	    // report achieved tok/s (pos-1 because the timer starts after first iteration)
839	    if (pos > 1) {
840	        long end = time_in_ms();
841	        fprintf(stderr, "achieved tok/s: %f\n", (pos-1) / (double)(end-start)*1000);
842	    }
843	
844	    free(prompt_tokens);
