895	                }
896	            }
897	            // get the user prompt
898	            if (pos == 0 && cli_user_prompt != NULL) {
899	                // user prompt for position 0 was passed in, use it
900	                strcpy(user_prompt, cli_user_prompt);
901	            } else {
902	                // otherwise get user prompt from stdin
903	                read_stdin("User: ", user_prompt, sizeof(user_prompt));
904	            }
905	            // render user/system prompts into the Llama 2 Chat schema
906	            if (pos == 0 && system_prompt[0] != '\0') {
907	                char system_template[] = "[INST] <<SYS>>\n%s\n<</SYS>>\n\n%s [/INST]";
908	                sprintf(rendered_prompt, system_template, system_prompt, user_prompt);
909	            } else {
910	                char user_template[] = "[INST] %s [/INST]";
911	                sprintf(rendered_prompt, user_template, user_prompt);
912	            }
913	            // encode the rendered prompt into tokens
914	            encode(tokenizer, rendered_prompt, 1, 0, prompt_tokens, &num_prompt_tokens);
915	            user_idx = 0; // reset the user index
916	            user_turn = 0;
917	            printf("Assistant: ");
918	        }
919	
920	        // determine the token to pass into the transformer next
921	        if (user_idx < num_prompt_tokens) {
922	            // if we are still processing the input prompt, force the next prompt token
923	            token = prompt_tokens[user_idx++];
924	        } else {
925	            // otherwise use the next token sampled from previous turn
926	            token = next;
927	        }
928	        // EOS (=2) token ends the Assistant turn
929	        if (token == 2) { user_turn = 1; }
930	
931	        // forward the transformer to get logits for the next token
932	        float* logits = forward(transformer, token, pos);
933	        next = sample(sampler, logits);
934	        pos++;
935	
936	        if (user_idx >= num_prompt_tokens && next != 2) {
937	            // the Assistant is responding, so print its output
938	            char* piece = decode(tokenizer, token, next);
939	            safe_printf(piece); // same as printf("%s", piece), but skips "unsafe" bytes
940	            fflush(stdout);
941	        }
942	        if (next == 2) { printf("\n"); }
943	    }
944	    printf("\n");
945	    free(prompt_tokens);
946	}
